style.css:
/* Tema Murmurat Eteric pentru Edge */

:root {
    --bg-main: #f2edeb;
    --accent-1: #b6aee2;
    --accent-2: #cfc3e0;
    --contrast-warm: #a88f8f;
    --text-main: #3a3535;
    --text-secondary: #6f6a7a;

    --font-title: "Cormorant Garamond", serif;
    --font-subtitle: "Inter", sans-serif;
    --font-body: "Source Serif Pro", serif;
    --font-ui: "Montserrat", sans-serif;
}

/* Fundal general */
body {
    background: var(--bg-main) !important;
    color: var(--text-main) !important;
    font-family: var(--font-body) !important;
}

/* Titluri */
h1, h2, h3 {
    font-family: var(--font-title) !important;
    color: var(--accent-1) !important;
}

/* Subtitluri */
h4, h5, h6 {
    font-family: var(--font-subtitle) !important;
    color: var(--accent-2) !important;
}

/* Linkuri */
a {
    color: var(--accent-1) !important;
}
a:hover {
    color: var(--contrast-warm) !important;
}

/* Butoane */
button {
    background: var(--contrast-warm) !important;
    color: #fff !important;
    border-radius: 6px !important;
    font-family: var(--font-ui) !important;
}
button:hover {
    background: var(--accent-1) !important;
}

/* Bare, carduri, panouri */
div, section, nav {
    border-color: var(--accent-2) !important;
}
